#!/usr/bin/env python3
"""Exact sgRNA counting for VAL-2, orientation-aware (run A sense, run B read2 = revcomp)."""
import gzip, json, os

COMP = str.maketrans("ACGTN", "TGCAN")
rc = lambda s: s.translate(COMP)[::-1]
SCAFFOLD = "GTTTTAGAGCTA"          # scaffold start, sense strand of the amplicon
TASK = "/task"

lib = []
for line in open(os.path.join(TASK, "input", "library.tsv")).read().splitlines()[1:]:
    if not line.strip():
        continue
    sg, seq, gene = line.split("\t")[:3]
    lib.append((sg, seq, gene))
by_seq = {seq: i for i, (sg, seq, gene) in enumerate(lib)}

samples = []
for line in open(os.path.join(TASK, "input", "samples.tsv")).read().splitlines()[1:]:
    if line.strip():
        samples.append(line.split("\t"))

counts = [[0] * len(samples) for _ in lib]
qc = {}
for j, row in enumerate(samples):
    sid, fqn = row[0], os.path.join(TASK, "input", "fastq", row[3])
    total = mapped = 0
    with gzip.open(fqn, "rt") as fh:
        for n, line in enumerate(fh):
            if n % 4 != 1:
                continue
            read = line.rstrip()
            total += 1
            for seq in (read, rc(read)):
                k = seq.find(SCAFFOLD)
                if k >= 20:
                    i = by_seq.get(seq[k - 20:k])
                    if i is not None:
                        counts[i][j] += 1
                        mapped += 1
                        break
    qc[sid] = {"total_reads": total, "mapped_reads": mapped}
    print(sid, total, mapped, "%.4f" % (mapped / total), flush=True)

os.makedirs(os.path.join(TASK, "output"), exist_ok=True)
with open(os.path.join(TASK, "output", "counts.tsv"), "w") as out:
    out.write("sgRNA\tgene\t" + "\t".join(r[0] for r in samples) + "\n")
    for (sg, seq, gene), row in zip(lib, counts):
        out.write(sg + "\t" + gene + "\t" + "\t".join(map(str, row)) + "\n")
with open(os.path.join(TASK, "output", "qc.json"), "w") as out:
    json.dump({"samples": qc}, out, indent=2)
EOF
